package org.brightstats.desktop;
import java.util.*;
import java.nio.file.Path;
import com.google.gson.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.geometry.Insets;
import javafx.stage.Window;
import org.brightstats.stats.*;
import org.brightstats.data.*;

/** A validated advanced specification editor with explicit variable-role proposals. */
final class AdjustedCopulaDialog {
    enum Context {OBSERVED,PLS,GSCA}
    record Settings(Context context,AdjustedCopula.Model system,int[] columns,Map<Integer,Integer> binaryBindings){
        Settings{Objects.requireNonNull(context);Objects.requireNonNull(system);columns=columns.clone();binaryBindings=Collections.unmodifiableMap(new LinkedHashMap<>(binaryBindings));if(context==Context.OBSERVED&&(columns.length!=system.names().size()||Arrays.stream(columns).anyMatch(c->c<0)||Arrays.stream(columns).distinct().count()!=columns.length||!binaryBindings.isEmpty())||context!=Context.OBSERVED&&columns.length!=0)throw new IllegalArgumentException("Observed variables need distinct dataset bindings; component contexts use their model definitions.");}
        @Override public int[] columns(){return columns.clone();}
        ComponentAdjustedCopula.Specification component(){return new ComponentAdjustedCopula.Specification(system,binaryBindings);}
        double[][] select(double[][] data){if(context!=Context.OBSERVED)throw new IllegalArgumentException("This selection is for observed variables.");int width=Matrices.width(data,3);double[][] out=new double[data.length][columns.length];for(int j=0;j<columns.length;j++){if(columns[j]>=width)throw new IllegalArgumentException("Observed binding is outside the dataset.");for(int i=0;i<data.length;i++)out[i][j]=data[i][columns[j]];}return out;}
    }
    private static final Gson JSON=new GsonBuilder().serializeNulls().setPrettyPrinting().setStrictness(Strictness.STRICT).create();
    private final Dialog<Settings> dialog=new Dialog<>();private final TextArea editor=new TextArea();private final Label status=UiAppearance.label("");private final Context context;
    private AdjustedCopulaDialog(Window owner,Settings settings){context=settings.context;dialog.initOwner(owner);dialog.setTitle("Adjusted copula system · "+context);dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);editor.setText(JSON.toJson(settings));editor.setPrefRowCount(25);editor.setPrefColumnCount(92);editor.setAccessibleText("Adjusted copula system JSON specification");Label guide=UiAppearance.label("Review the proposed variable roles before running. Endogeneity must be justified by your theory. Indices refer to system.names; observed columns and binaryBindings refer to dataset columns. Classify every parent once as endogenous continuous, continuous exogenous or binary 0/1. extensions use target/factors; probes use original system units. Multiple corrections share case draws. Default roles are proposals, not endogeneity findings.");guide.setWrapText(true);guide.setMaxWidth(850);Button format=UiAppearance.button("Validate and format");format.setOnAction(event->{try{var value=read();editor.setText(JSON.toJson(value));status.setText("Schema valid. Numerical identification and category sizes are checked during estimation.");}catch(RuntimeException problem){status.setText(problem.getMessage());}});VBox content=new VBox(10,guide,editor,new HBox(10,format,status));content.setPadding(new Insets(12));VBox.setVgrow(editor,Priority.ALWAYS);dialog.getDialogPane().setContent(content);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{read();}catch(RuntimeException problem){status.setText(problem.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?read():null);}
    private Settings read(){if(editor.getText().length()>1048576)throw new IllegalArgumentException("Specification exceeds one MiB of text.");var object=JSON.fromJson(editor.getText(),JsonObject.class);var settings=parse(object);Context selected=settings.context;if(selected!=context)throw new IllegalArgumentException("Keep the current context; choose another analysis action to change it.");return settings;}
    static Settings parse(JsonObject object){if(object==null||!object.has("context")||!object.has("system"))throw new IllegalArgumentException("Include context and system objects in the specification.");return new Settings(Context.valueOf(object.get("context").getAsString()),AdjustedCopulaInput.model(object.get("system")),object.has("columns")?PlsModelInput.indices(object.get("columns")):new int[0],AdjustedCopulaInput.bindings(object.get("binaryBindings")));}
    static Optional<Settings> show(Window owner,Settings settings){return new AdjustedCopulaDialog(owner,settings).dialog.showAndWait();}
    static Settings smoke(Window owner,Settings settings,Path image)throws Exception{var editor=new AdjustedCopulaDialog(owner,settings);editor.dialog.show();String original=editor.editor.getText();editor.editor.setText("{}");((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing()||editor.status.getText().isBlank())throw new AssertionError("Invalid adjusted-copula dialog closed");editor.editor.setText(original);var result=editor.read();editor.dialog.getDialogPane().applyCss();editor.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,editor.dialog.getDialogPane(),1);editor.dialog.setResult(null);editor.dialog.close();return result;}
    private static boolean binary(double[][] data,int column){boolean zero=false,one=false;for(var row:data){if(row[column]==0)zero=true;else if(row[column]==1)one=true;else return false;}return zero&&one;}
    static Settings observed(List<String> names,double[][] data){int count=Math.min(names.size(),8);if(count<2)throw new IllegalArgumentException("Use at least two numeric columns.");var selected=names.subList(0,count);int target=count-1;List<PlsSem.Edge> paths=new ArrayList<>();List<Integer> binary=new ArrayList<>(),continuous=new ArrayList<>();for(int source=0;source<target;source++){paths.add(new PlsSem.Edge(source,target));(binary(data,source)?binary:continuous).add(source);}if(continuous.isEmpty())throw new IllegalArgumentException("A continuous potentially endogenous predictor is required.");int endogenous=continuous.removeFirst();var correction=new AdjustedCopula.Correction(target,new int[]{endogenous},continuous.stream().mapToInt(Integer::intValue).toArray(),binary.stream().mapToInt(Integer::intValue).toArray(),true);return new Settings(Context.OBSERVED,new AdjustedCopula.Model(selected,paths,List.of(),List.of(correction),List.of()),java.util.stream.IntStream.range(0,count).toArray(),Map.of());}
    static Settings component(ComponentScores.Model model,double[][] data){Map<Integer,Integer> bindings=new LinkedHashMap<>();for(int component=0;component<model.names().size();component++){final int index=component;if(model.paths().stream().anyMatch(e->e.target()==index))continue;int column=-1;if(model.estimator()==ComponentScores.Estimator.PLS){int[] selected=model.blocks().get(component).columns();if(selected.length==1)column=selected[0];}else{int[] columns=model.gscaColumns();boolean[][] mask=model.gscaModel().weights();int count=0;for(int row=0;row<mask.length;row++)if(mask[row][component]){count++;column=columns[row];}if(count!=1)column=-1;}if(column>=0&&column<data[0].length&&binary(data,column))bindings.put(component,column);}
        List<AdjustedCopula.Correction> corrections=new ArrayList<>();Set<Integer> usedBinary=new HashSet<>();for(int target=0;target<model.names().size();target++){List<Integer> continuous=new ArrayList<>(),binary=new ArrayList<>();for(var path:model.paths())if(path.target()==target)(bindings.containsKey(path.source())?binary:continuous).add(path.source());if(continuous.isEmpty())continue;int endogenous=continuous.removeFirst();corrections.add(new AdjustedCopula.Correction(target,new int[]{endogenous},continuous.stream().mapToInt(Integer::intValue).toArray(),binary.stream().mapToInt(Integer::intValue).toArray(),true));usedBinary.addAll(binary);}if(corrections.isEmpty())throw new IllegalArgumentException("Configure a structural target with a continuous parent first.");bindings.keySet().retainAll(usedBinary);return new Settings(Context.valueOf(model.estimator().name()),new AdjustedCopula.Model(model.names(),model.paths(),List.of(),corrections,List.of()),new int[0],bindings);}
}
